dtsPropsFor.TextInput:
/** Visual density. `md` (default) = 44px / $text-base, for forms and primary surfaces. `sm` = 28px / $text-small, for dense panels (inspectors, toolbars). */
size?: 'sm' | 'md';
className?: string;
/* Extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'size'> — EVERY native <input> attribute passes through. The common ones, listed explicitly: */
type?: 'text' | 'email' | 'password' | 'search' | 'url' | 'tel' | 'number' | 'date' | 'time';
placeholder?: string;
value?: string | number;
defaultValue?: string | number;
disabled?: boolean;
readOnly?: boolean;
required?: boolean;
name?: string;
id?: string;
autoComplete?: string;
maxLength?: number;
min?: number | string;
max?: number | string;
step?: number | string;
onChange?: React.ChangeEventHandler<HTMLInputElement>;
onFocus?: React.FocusEventHandler<HTMLInputElement>;
onBlur?: React.FocusEventHandler<HTMLInputElement>;
onKeyDown?: React.KeyboardEventHandler<HTMLInputElement>;
style?: React.CSSProperties;
'aria-label'?: string;

dtsPropsFor.Textarea:
/** Density. `md` (default) = $text-base; `sm` = $text-small for dense panels. */
size?: 'sm' | 'md';
className?: string;
/* Extends Omit<React.TextareaHTMLAttributes<HTMLTextAreaElement>, 'size'> — EVERY native <textarea> attribute passes through. Vertically resizable by the user. */
placeholder?: string;
value?: string;
defaultValue?: string;
/** Visible line count. Note: content longer than `rows` is clipped without a visible scrollbar in a static render. */
rows?: number;
cols?: number;
disabled?: boolean;
readOnly?: boolean;
required?: boolean;
name?: string;
id?: string;
maxLength?: number;
onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;
onFocus?: React.FocusEventHandler<HTMLTextAreaElement>;
onBlur?: React.FocusEventHandler<HTMLTextAreaElement>;
style?: React.CSSProperties;
'aria-label'?: string;

dtsPropsFor.IconButton:
/** Pressed/engaged state — $demure fill (a split toggle that is split, a popover trigger that is open). */
active?: boolean;
/** @default 'dense' — the field-adjacent square, exactly $control-height-dense (28px), so it lines up with size='sm' inputs by definition. */
size?: 'dense';
/* Extends React.ButtonHTMLAttributes<HTMLButtonElement> — native button props pass through. */
children?: React.ReactNode;
onClick?: React.MouseEventHandler<HTMLButtonElement>;
disabled?: boolean;
type?: 'button' | 'submit' | 'reset';
className?: string;
style?: React.CSSProperties;
'aria-label'?: string;

dtsPropsFor.SegmentedControl:
/** The segments. `label` may be a ReactNode (e.g. an icon); pass `title` when the label is not readable text. */
options: Array<{ label: React.ReactNode; value: string; title?: string }>;
/** Controlled selected value — this component has no internal state. */
value: string;
onChange: (value: string) => void;
/** @default 'sm' */
size?: 'sm' | 'md';
className?: string;
/* Extends Omit<React.HTMLAttributes<HTMLDivElement>, 'onChange'>. */
style?: React.CSSProperties;

dtsPropsFor.DataTable:
/** Column definitions. */
columns: Array<{
  id: string;
  /** Column header label. */
  header: string;
  /** Hover explanation, rendered as the header's native `title` tooltip; adds a dotted underline so the affordance is visible. Use for abbreviations and derived metrics ("OI", "Edge"). */
  headerTitle?: string;
  /** Renders a small info button in the header that fires this callback — for a fuller explanation (dialog, side panel) than a tooltip can carry. Does not interfere with sorting. */
  onInfo?: () => void;
  /** Key on the row object used to read the cell value and to sort. Omit for a display-only column (then `cell` is required). */
  accessorKey?: string;
  /** Custom cell renderer; receives the accessed value and the full row object. */
  cell?: (value: unknown, row: any) => React.ReactNode;
  /** Defaults to `true` when `accessorKey` is set, `false` otherwise. */
  sortable?: boolean;
  /** Fixed width as a pixel number or any CSS width string. */
  width?: number | string;
  /** @default 'left' */
  align?: 'left' | 'center' | 'right';
}>;
/** Row data. */
data: any[];
/** Returns a stable unique id per row. Defaults to the row index. */
getRowId?: (row: any, index: number) => string;
/** Per-row actions rendered in an overflow menu. Pass an array for uniform actions, or a function to vary them per row; `{ separator: true }` inserts a divider. */
rowActions?: Array<{ label: string; onSelect: (row: any) => void; destructive?: boolean } | { separator: true }> | ((row: any) => Array<{ label: string; onSelect: (row: any) => void; destructive?: boolean } | { separator: true }>);
/** Enable row-selection checkboxes. */
selectable?: boolean;
/** Called whenever the selection set changes, with the current selected row ids. */
onSelectionChange?: (ids: string[]) => void;
/** Column id to sort by on initial render. */
defaultSortId?: string;
/** @default 'asc' */
defaultSortDirection?: 'asc' | 'desc';
/** Text shown when `data` is empty. */
emptyMessage?: string;
/** Typography scale for headers, cells, and empty state. `sm` = $text-small (default), `md` = $text-base. */
size?: 'sm' | 'md';
